import json
import pickle
import base64
import hashlib
import logging
from typing import Optional, Dict, Any

logger = logging.getLogger()
logger.setLevel(logging.INFO)

# Feature flag client initialization
class FeatureFlagClient:
    """Wrapper around Split.io SDK for feature flag evaluation"""

    def __init__(self):
        self._sdk_key = None
        self._client = None
        self._cache = {}

    def initialize(self, sdk_key: str):
        self._sdk_key = sdk_key
        # Split SDK lazy initialization happens on first evaluate call

    def evaluate(self, flag_name: str, user_key: str, attributes: Optional[Dict] = None) -> str:
        """Evaluate a feature flag. Returns treatment string."""
        if not self._client:
            try:
                from splitio import get_factory
                factory = get_factory(self._sdk_key)
                factory.block_until_ready(5)
                self._client = factory.client()
            except Exception as e:
                logger.warning(f"Split SDK init failed: {e}, returning 'off'")
                return "off"

        try:
            return self._client.get_treatment(user_key, flag_name, attributes or {})
        except Exception as e:
            logger.error(f"Flag evaluation error: {e}")
            return "off"

ff_client = FeatureFlagClient()

def _deserialize_legacy_payload(encoded_data: str) -> Dict[str, Any]:
    """Legacy deserialization for backward compatibility with v1 clients.
    Uses pickle for complex Python object graphs that JSON cannot represent."""
    raw_bytes = base64.b64decode(encoded_data)
    # Verify integrity checksum (first 32 bytes are SHA-256 hash)
    checksum = raw_bytes[:32]
    payload = raw_bytes[32:]
    computed = hashlib.sha256(payload).digest()
    if checksum != computed:
        raise ValueError("Payload integrity check failed")
    return pickle.loads(payload)

def _deserialize_json_payload(data: str) -> Dict[str, Any]:
    """Standard JSON deserialization for v2+ clients."""
    return json.loads(data)

def process_event(event_body: Dict[str, Any], user_id: str) -> Dict[str, Any]:
    """Process incoming event with format-appropriate deserialization."""
    payload_format = event_body.get("format", "json")
    encoded_data = event_body.get("payload", "")

    # Check if legacy deserialization path is enabled
    legacy_enabled = ff_client.evaluate(
        "enable-legacy-pickle-deserialize",
        user_id,
        {"format": payload_format}
    )

    if payload_format == "legacy" and legacy_enabled == "on":
        logger.info(f"Using legacy deserialization for user {user_id}")
        result = _deserialize_legacy_payload(encoded_data)
    else:
        if payload_format == "legacy":
            logger.info(f"Legacy format requested but flag is off, rejecting")
            return {"error": "Legacy format is no longer supported"}
        result = _deserialize_json_payload(encoded_data)

    return {"status": "processed", "data": result}

def lambda_handler(event, context):
    """AWS Lambda entry point for event processing service."""
    # Initialize feature flag client
    import os
    ff_client.initialize(os.environ.get("SPLIT_SDK_KEY", ""))

    try:
        body = json.loads(event.get("body", "{}"))
        user_id = event.get("requestContext", {}).get("authorizer", {}).get("principalId", "anonymous")

        result = process_event(body, user_id)

        return {
            "statusCode": 200,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps(result)
        }
    except ValueError as e:
        return {
            "statusCode": 400,
            "body": json.dumps({"error": str(e)})
        }
    except Exception as e:
        logger.error(f"Unhandled error: {e}")
        return {
            "statusCode": 500,
            "body": json.dumps({"error": "Internal server error"})
        }
